 const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`${left!} ${top} ${right!-left!} ${bottom-top}`);svg.setAttribute('preserveAspectRatio','xMidYMid meet');svg.dataset.practiceBar=String(bar+1);const style=doc.querySelector('style');if(style)svg.append(document.importNode(style,true));svg.append(document.importNode(system,true));const clone=svg.querySelector(`#system-${first.system+1}`)!;clone.removeAttribute('id');clone.querySelectorAll('.janko-measure-num,.janko-system-bracket').forEach(e=>e.remove());
 // Give each authored separator one side. Ordinary/double/end rules belong
